28	/// Run a request.
29	///
30	/// This is the "main loop" of entire ureq.
31	pub(crate) fn run(
32	    agent: &Agent,
33	    mut request: Request<()>,
34	    mut body: SendBody,
35	) -> Result<Response<Body>, Error> {
36	    let mut redirect_count = 0;
37	
38	    // Configuration on the request level overrides the agent level.
39	    let (config, request_level) = request
40	        .extensions_mut()
41	        .remove::<RequestLevelConfig>()
42	        .map(|rl| (Arc::new(rl.0), true))
43	        .unwrap_or_else(|| (agent.config.clone(), false));
44	
45	    let force_send_body = request.extensions_mut().remove::<ForceSendBody>().is_some();
46	
47	    let mut redirect_history: Option<Vec<Uri>> =
48	        config.save_redirect_history().then_some(Vec::new());
49	
50	    let timeouts = config.timeouts();
51	
52	    let mut timings = CallTimings::new(timeouts, CurrentTime::default()).with_io_timeouts(&config);
53	
54	    // A template of the request currently being sent. This is used to
55	    // rebuild the request when a 307/308 redirect requires the body to
56	    // be replayed. The template only ever holds headers from the original
57	    // request; headers ureq adds automatically (such as Content-Length)
58	    // are amended on the call and recomputed for each redirect hop.
59	    let mut template = request_template(&request);
60	
61	    let mut call = Call::new(request)?;
62	
63	    if force_send_body {
64	        call.force_send_body();
65	    }
66	
67	    call.allow_non_standard_methods(config.allow_non_standard_methods());
68	
69	    let (response, handler) = loop {
70	        let timeout = timings.next_timeout(Timeout::Global);
71	        let timed_out = match timeout.after {
72	            Duration::Exact(v) => v.is_zero(),
73	            Duration::NotHappening => false,
74	        };
75	        if timed_out {
76	            return Err(Error::Timeout(Timeout::Global));
77	        }
78	
79	        match call_run(
80	            agent,
81	            &config,
82	            request_level,
83	            call,
84	            &mut body,
85	            redirect_count,
86	            &mut redirect_history,
87	            &mut timings,
88	        )? {
89	            // Follow redirect
90	            CallResult::Redirect(rcall, rtimings, location) => {
91	                redirect_count += 1;
92	
93	                let status = rcall.status();
94	                let is_retain_status = matches!(
95	                    status,
96	                    StatusCode::TEMPORARY_REDIRECT | StatusCode::PERMANENT_REDIRECT
97	                );
98	                let method_needs_body = matches!(
99	                    template.method(),
100	                    &Method::POST | &Method::PUT | &Method::PATCH
101	                );
102	
103	                call = if is_retain_status && method_needs_body {
104	                    // A 307/308 redirect on POST/PUT/PATCH must resend the
105	                    // request body. This is only possible for bodies held
106	                    // in memory, and only when the caller opted in.
107	                    if !config.redirect_body_replay() || !body.is_replayable() {
108	                        return Err(Error::RedirectFailed);
109	                    }
110	
111	                    body.rewind();
112	
113	                    let request = redirect_replay_request(&template, location.as_ref(), &config)?;
114	
115	                    debug!(
116	                        "Redirect ({}): {} {:?}",
117	                        status,
118	                        request.method(),
119	                        DebugUri(request.uri())
120	                    );
121	
122	                    Call::new(request)?
123	                } else {
124	                    let call = handle_redirect(rcall, &config)?;
125	
126	                    // If the new method doesn't need a body, clear it.
127	                    // This prevents Content-Length/Transfer-Encoding headers from being added
128	                    // on methods like GET that don't send bodies (e.g., POST->GET redirects).
129	                    let method = call.method();
130	                    if !matches!(method, &Method::POST | &Method::PUT | &Method::PATCH) {
131	                        body.remove();
132	                    }
133	
134	                    call
135	                };
136	
137	                template = request_template_from_call(&call);
138	
139	                timings = rtimings.new_call();
140	            }
141	
142	            // Return response
143	            CallResult::Response(response, handler) => break (response, handler),
144	        }
145	    };
146	
147	    let (mut parts, _) = response.into_parts();
148	
149	    let recv_body_mode = handler
150	        .call
151	        .as_ref()
152	        .map(|f| f.body_mode())
153	        .unwrap_or(BodyMode::NoBody);
154	
155	    let info = ResponseInfo::new(&parts.headers, recv_body_mode);
156	
157	    // If the body will be decompressed, strip Content-Encoding and Content-Length
158	    // from the response headers. The Content-Length no longer matches the
159	    // decompressed body size, and Content-Encoding no longer applies since
160	    // the body is delivered to the caller already decompressed (RFC 9110 §8.7).
161	    if info.is_decompressing() {
162	        parts.headers.remove(http::header::CONTENT_ENCODING);
163	        parts.headers.remove(http::header::CONTENT_LENGTH);
164	    }
165	
166	    let body = Body::new(handler, info);
167	
168	    let response = Response::from_parts(parts, body);
169	
170	    let status = response.status();
171	    let is_err = status.is_client_error() || status.is_server_error();
172	
173	    if config.http_status_as_error() && is_err {
174	        return Err(Error::StatusCode(status.as_u16()));
175	    }
176	
177	    Ok(response)
178	}
