307	enum CallResult {
308	    /// Call resulted in a redirect.
309	    Redirect(Call<Redirect>, CallTimings, Option<HeaderValue>),
310	
311	    /// Call resulted in a response.
312	    Response(Response<()>, BodyHandler),
