315	fn add_headers(
316	    call: &mut Call<Prepare>,
317	    agent: &Agent,
318	    config: &Config,
319	    body: &mut SendBody,
320	    uri: &Uri,
321	) -> Result<(), Error> {
322	    let headers = call.headers();
323	
324	    let send_body_mode = if headers.has_send_body_mode() {
325	        None
326	    } else {
327	        Some(body.body_mode()?)
328	    };
329	    let has_header_accept_enc = headers.has_accept_encoding();
330	    let has_header_ua = headers.has_user_agent();
331	    let has_header_accept = headers.has_accept();
332	
333	    #[cfg(not(feature = "cookies"))]
334	    {
335	        let _ = agent;
336	        let _ = uri;
337	    }
338	    #[cfg(feature = "cookies")]
339	    {
340	        let value = agent.jar.get_request_cookies(uri);
341	        if !value.is_empty() {
342	            let value = HeaderValue::from_str(&value)
343	                .map_err(|_| Error::CookieValue("Cookie value is an invalid http-header"))?;
344	            call.header(header::COOKIE, value)?;
345	        }
346	    }
347	
348	    {
349	        static ACCEPTS: LazyLock<String> = LazyLock::new(|| {
350	            #[allow(unused_mut)]
351	            let mut value = String::with_capacity(10);
352	            #[cfg(feature = "gzip")]
353	            value.push_str("gzip");
354	            #[cfg(all(feature = "gzip", feature = "brotli"))]
355	            value.push_str(", ");
356	            #[cfg(feature = "brotli")]
357	            value.push_str("br");
358	            value
359	        });
360	
361	        let accepts = &*ACCEPTS;
362	
363	        if !has_header_accept_enc {
364	            if let Some(v) = config.accept_encoding().as_str(accepts) {
365	                // unwrap is ok because above ACCEPTS will produce a valid value,
366	                // or the value is user provided in which case it must be valid.
367	                let value = HeaderValue::from_str(v).unwrap();
368	                call.header(header::ACCEPT_ENCODING, value)?;
369	            }
370	        }
371	    }
372	
373	    if let Some(send_body_mode) = send_body_mode {
374	        match send_body_mode {
375	            BodyMode::LengthDelimited(v) => {
376	                let value = HeaderValue::from(v);
377	                call.header(header::CONTENT_LENGTH, value)?;
378	            }
379	            BodyMode::Chunked => {
380	                let value = HeaderValue::from_static("chunked");
381	                call.header(header::TRANSFER_ENCODING, value)?;
382	            }
383	            _ => {}
384	        }
385	    }
386	
387	    if !has_header_ua {
388	        // unwrap is ok because a user might override the agent, and if they
389	        // set bad values, it's not really ureq's problem.
390	        if let Some(v) = config.user_agent().as_str(DEFAULT_USER_AGENT) {
391	            let value = HeaderValue::from_str(v).unwrap();
392	            call.header(header::USER_AGENT, value)?;
393	        }
394	    }
395	
396	    if !has_header_accept {
397	        // unwrap is ok because a user might override accepts header, and if they
398	        // set bad values, it's not really ureq's problem.
399	        if let Some(v) = config.accept().as_str("*/*") {
400	            let value = HeaderValue::from_str(v).unwrap();
401	            call.header(header::ACCEPT, value)?;
402	        }
403	    }
404	
405	    Ok(())
406	}
