408	fn connect(
409	    agent: &Agent,
410	    config: &Config,
411	    request_level: bool,
412	    uri: &Uri,
413	    timings: &mut CallTimings,
414	) -> Result<Connection, Error> {
415	    // Before resolving the URI we need to ensure it is a full URI. We
416	    // cannot make requests with partial uri like "/path".
417	    uri.ensure_valid_url()?;
418	
419	    let is_proxy = config.proxy().is_some();
420	
421	    // For most proxy configs, the proxy itself should resolve the host name we are connecting to.
422	    // However for SOCKS4, we must do it and pass the resolved IP to the proxy.
423	    let is_proxy_local_resolve = config.proxy().map(|p| p.resolve_target()).unwrap_or(false);
424	
425	    // Tells if this host matches NO_PROXY
426	    let is_no_proxy = config.proxy().map(|p| p.is_no_proxy(uri)).unwrap_or(false);
427	
428	    let addrs = if is_no_proxy || !is_proxy || is_proxy_local_resolve {
429	        agent
430	            .resolver
431	            .resolve(uri, config, timings.next_timeout(Timeout::Resolve))?
432	    } else {
433	        agent.resolver.empty()
434	    };
435	
436	    timings.record_time(Timeout::Resolve);
437	
438	    let details = ConnectionDetails {
439	        uri,
440	        addrs,
441	        resolver: &*agent.resolver,
442	        config,
443	        request_level,
444	        now: timings.now(),
445	        timeout: timings.next_timeout(Timeout::Connect),
446	        current_time: timings.current_time(),
447	        run_connector: agent.run_connector.clone(),
448	    };
449	
450	    let use_pool = config.can_share_pool_with(&agent.config);
451	    let max_idle_age = config.max_idle_age().into();
452	    let connection = agent.pool.connect(&details, max_idle_age, use_pool)?;
453	
454	    if details.needs_tls() && !connection.is_tls() {
455	        return Err(Error::TlsRequired);
456	    }
457	
458	    timings.record_time(Timeout::Connect);
459	
460	    Ok(connection)
461	}
462	
463	fn send_request(
464	    mut call: Call<SendRequest>,
465	    connection: &mut Connection,
466	    timings: &mut CallTimings,
467	) -> Result<SendRequestResult, Error> {
468	    loop {
469	        if call.can_proceed() {
470	            break;
471	        }
472	
473	        let buffers = connection.buffers();
474	        let amount = call.write(buffers.output())?;
475	        let timeout = timings.next_timeout(Timeout::SendRequest);
476	        connection.transmit_output(amount, timeout)?;
477	    }
478	
479	    timings.record_time(Timeout::SendRequest);
480	
481	    // The request might be misconfigured.
482	    let call = call.proceed()?;
483	
484	    // We checked can_proceed() above, this unwrap is fine.
485	    Ok(call.unwrap())
486	}
487	
488	fn await_100(
489	    mut call: Call<Await100>,
490	    connection: &mut Connection,
491	    timings: &mut CallTimings,
492	) -> Result<Await100Result, Error> {
493	    while call.can_keep_await_100() {
494	        let timeout = timings.next_timeout(Timeout::Await100);
495	
496	        if timeout.after.is_zero() {
497	            if timeout.reason == Timeout::Await100 {
498	                // Stop waiting for 100-continue.
499	                break;
500	            }
501	            return Err(Error::Timeout(timeout.reason));
502	        }
503	
504	        match connection.maybe_await_input(timeout) {
505	            Ok(_) => {
506	                let input = connection.buffers().input();
507	                if input.is_empty() {
508	                    return Err(Error::disconnected("await_100 empty input"));
509	                }
510	
511	                let amount = call.try_read_100(input)?;
512	                if amount > 0 {
513	                    connection.consume_input(amount);
514	                    break;
515	                }
516	            }
517	            Err(Error::Timeout(Timeout::Await100)) => {
518	                // If we get a timeout while waiting for input, that is not an error,
519	                // we progress to send the request body.
520	                break;
521	            }
522	            Err(e) => return Err(e),
523	        }
524	    }
525	
526	    timings.record_time(Timeout::Await100);
527	
528	    // A misconfigured request might surface here.
529	    let call = call.proceed()?;
530	
531	    Ok(call)
532	}
