534	fn send_body(
535	    mut call: Call<SendBodyState>,
536	    body: &mut SendBody,
537	    connection: &mut Connection,
538	    timings: &mut CallTimings,
539	) -> Result<Call<RecvResponse>, Error> {
540	    loop {
541	        if call.can_proceed() {
542	            break;
543	        }
544	
545	        let buffers = connection.buffers();
546	
547	        let (tmp, output) = buffers.tmp_and_output();
548	
549	        let input_len = tmp.len();
550	
551	        let input_fitting_in_output = call.calculate_max_input(output.len());
552	        let max_input = input_len.min(input_fitting_in_output);
553	
554	        let output_used = if !call.is_chunked() {
555	            // For non-chunked, The body can be written directly to the output.
556	            // This optimizes away a memcopy if we were to go via call.write().
557	            let output_used = body.read(output)?;
558	
559	            // Size checking is still in the call.
560	            call.consume_direct_write(output_used)?;
561	
562	            output_used
563	        } else {
564	            let tmp = &mut tmp[..max_input];
565	            let n = body.read(tmp)?;
566	
567	            let (input_used, output_used) = call.write(&tmp[..n], output)?;
568	
569	            // Since output is "a bit" larger than the input (compensate for chunk ovexrhead),
570	            // the entire input we read from the body should also be shipped to the output.
571	            assert!(input_used == n);
572	
573	            output_used
574	        };
575	
576	        let timeout = timings.next_timeout(Timeout::SendBody);
577	        connection.transmit_output(output_used, timeout)?;
578	    }
579	
580	    timings.record_time(Timeout::SendBody);
581	    Ok(call.proceed().unwrap())
582	}
583	
584	fn recv_response(
585	    mut call: Call<RecvResponse>,
586	    connection: &mut Connection,
587	    config: &Config,
588	    timings: &mut CallTimings,
589	    is_following_redirects: bool,
590	) -> Result<(Response<()>, RecvResponseResult), Error> {
591	    let response = loop {
592	        let timeout = timings.next_timeout(Timeout::RecvResponse);
593	        let made_progress = connection.maybe_await_input(timeout)?;
594	
595	        let input = connection.buffers().input();
596	
597	        // If cookies are disabled, we can allow ourselves to follow
598	        // the redirect as soon as we discover the `Location` header.
599	        // There are plenty of broken servers out there that don't send
600	        // the finishing \r\n on redirects. With cookies off, we can
601	        // handle that situation.
602	        //
603	        // If cookies are enabled, we risk mising a `Set-Cookie` header
604	        // with such a strategy.
605	        let cookies_enabled = cfg!(feature = "cookies");
606	
607	        // If we are not following redirects, do not allow partial returned
608	        // 302 responses.
609	        let allow_partial_redirect = !cookies_enabled && is_following_redirects;
610	
611	        let (amount, maybe_response) = call.try_response(input, allow_partial_redirect)?;
612	
613	        let check_size = if maybe_response.is_some() {
614	            // We got a parsed response, ensure the size is within
615	            // configured parameters.
616	            amount
617	        } else {
618	            // We did not parse a response, if input is too large,
619	            // we stop trying to get more data.
620	            input.len()
621	        };
622	
623	        if check_size > config.max_response_header_size() {
624	            return Err(Error::LargeResponseHeader(
625	                input.len(),
626	                config.max_response_header_size(),
627	            ));
628	        }
629	
630	        connection.consume_input(amount);
631	
632	        if let Some(response) = maybe_response {
633	            assert!(call.can_proceed());
634	            break response;
635	        } else if !made_progress {
636	            return Err(Error::disconnected("recv_respone made no progress"));
637	        }
638	    };
639	
640	    timings.record_time(Timeout::RecvResponse);
641	    Ok((response, call.proceed().unwrap()))
642	}
