662	/// A snapshot of a request, used to rebuild it when a 307/308 redirect
663	/// requires the body to be replayed.
664	///
665	/// Extensions are not carried over. They are either consumed when setting
666	/// up the call (such as [`RequestLevelConfig`]) or not relevant for a
667	/// redirected request.
668	fn request_template(request: &Request<()>) -> Request<()> {
669	    let mut template = Request::new(());
670	    *template.method_mut() = request.method().clone();
671	    *template.uri_mut() = request.uri().clone();
672	    *template.version_mut() = request.version();
673	    *template.headers_mut() = request.headers().clone();
674	    template
675	}
676	
677	fn request_template_from_call(call: &Call<Prepare>) -> Request<()> {
678	    let mut template = Request::new(());
679	    *template.method_mut() = call.method().clone();
680	    *template.uri_mut() = call.uri().clone();
681	    *template.version_mut() = call.version();
682	    *template.headers_mut() = call.headers().clone();
683	    template
684	}
