686	/// Build the request for a 307/308 redirect that replays the request body.
687	///
688	/// The method and headers are retained from the previous request. This
689	/// mirrors the header handling in ureq-proto's redirect logic, except that
690	/// a caller-provided `Content-Length`/`Transfer-Encoding` is kept, since the
691	/// replayed body is byte-identical to what was first sent.
692	fn redirect_replay_request(
693	    template: &Request<()>,
694	    location: Option<&HeaderValue>,
695	    config: &Config,
696	) -> Result<Request<()>, Error> {
697	    let header = location.ok_or(ureq_proto::Error::NoLocationHeader)?;
698	
699	    let location = header.to_str().map_err(|_| {
700	        ureq_proto::Error::BadLocationHeader(String::from_utf8_lossy(header.as_bytes()).to_string())
701	    })?;
702	
703	    let uri = new_uri_from_location(template.uri(), location)?;
704	
705	    let keep_auth_header = match config.redirect_auth_headers() {
706	        RedirectAuthHeaders::SameHost => can_redirect_auth_header(template.uri(), &uri),
707	        _ => false,
708	    };
709	
710	    let mut request = request_template(template);
711	    *request.uri_mut() = uri;
712	
713	    // Mutate the request to remove headers we cannot keep in the redirect.
714	    let headers = request.headers_mut();
715	    if !keep_auth_header {
716	        headers.remove(header::AUTHORIZATION);
717	    }
718	    headers.remove(header::COOKIE);
719	
720	    Ok(request)
721	}
722	
723	fn can_redirect_auth_header(prev: &Uri, next: &Uri) -> bool {
724	    let host_prev = prev.authority().map(|a| a.host());
725	    let host_next = next.authority().map(|a| a.host());
726	    let scheme_prev = prev.scheme();
727	    let scheme_next = next.scheme();
728	    host_prev == host_next && (scheme_prev == scheme_next || scheme_next == Some(&Scheme::HTTPS))
729	}
