15	#[derive(Debug, Clone)]
16	struct Recorded {
17	    method: String,
18	    target: String,
19	    headers: Vec<(String, String)>,
20	    body: Vec<u8>,
21	}
22	
23	impl Recorded {
24	    fn header(&self, name: &str) -> Option<&str> {
25	        self.headers
26	            .iter()
27	            .find(|(k, _)| k.eq_ignore_ascii_case(name))
28	            .map(|(_, v)| v.as_str())
29	    }
30	}
31	
32	#[derive(Debug)]
33	struct Response {
34	    status: u16,
35	    headers: Vec<(String, String)>,
36	    body: Vec<u8>,
37	}
38	
39	impl Response {
40	    fn new(status: u16) -> Self {
41	        Response {
42	            status,
43	            headers: vec![],
44	            body: vec![],
45	        }
46	    }
47	
48	    fn header(mut self, name: &str, value: &str) -> Self {
49	        self.headers.push((name.to_string(), value.to_string()));
50	        self
51	    }
52	
53	    fn body(mut self, body: &[u8]) -> Self {
54	        self.body = body.to_vec();
55	        self
56	    }
57	}
58	
59	enum Reply {
60	    /// Respond without reading the request body. For use with
61	    /// `Expect: 100-continue` requests, where the client waits
62	    /// for the server before sending the body.
63	    Now(Response),
64	    /// Read the request body (answering 100-continue if asked),
65	    /// record it, then respond.
66	    WithBody(Response),
67	}
68	
69	struct Server {
70	    addr: SocketAddr,
71	    received: Arc<Mutex<Vec<Recorded>>>,
72	}
73	
74	impl Server {
75	    fn url(&self, path: &str) -> String {
76	        format!("http://{}{}", self.addr, path)
77	    }
78	
79	    fn received(&self) -> Vec<Recorded> {
80	        self.received.lock().unwrap().clone()
81	    }
