84	/// Start a server that handles one request per connection and records it.
85	fn serve<F>(handler: F) -> Server
86	where
87	    F: Fn(SocketAddr, &Recorded) -> Reply + Send + 'static,
88	{
89	    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
90	    let addr = listener.local_addr().unwrap();
91	    let received = Arc::new(Mutex::new(vec![]));
92	    let received2 = received.clone();
93	
94	    thread::spawn(move || {
95	        for stream in listener.incoming() {
96	            let stream = match stream {
97	                Ok(s) => s,
98	                Err(_) => break,
99	            };
100	            handle_conn(stream, &handler, &received2, addr);
101	        }
102	    });
103	
104	    Server { addr, received }
105	}
106	
107	fn handle_conn<F>(
108	    stream: TcpStream,
109	    handler: &F,
110	    received: &Arc<Mutex<Vec<Recorded>>>,
111	    addr: SocketAddr,
112	) where
113	    F: Fn(SocketAddr, &Recorded) -> Reply,
114	{
115	    stream
116	        .set_read_timeout(Some(Duration::from_secs(10)))
117	        .unwrap();
118	
119	    let mut reader = BufReader::new(&stream);
120	
121	    let mut req = match read_head(&mut reader) {
122	        Ok(r) => r,
123	        Err(_) => return,
124	    };
125	
126	    let reply = handler(addr, &req);
127	
128	    let response = match reply {
129	        Reply::Now(r) => r,
130	        Reply::WithBody(r) => {
131	            let wants_100 = req
132	                .header("expect")
133	                .map(|v| v.eq_ignore_ascii_case("100-continue"))
134	                .unwrap_or(false);
135	            if wants_100
136	                && (&stream)
137	                    .write_all(b"HTTP/1.1 100 Continue\r\n\r\n")
138	                    .is_err()
139	            {
140	                return;
141	            }
142	            match read_body(&mut reader, &req) {
143	                Ok(b) => req.body = b,
144	                Err(_) => return,
145	            }
146	            r
147	        }
148	    };
149	
150	    received.lock().unwrap().push(req);
151	
152	    let mut out = format!("HTTP/1.1 {} OK\r\n", response.status);
153	    for (k, v) in &response.headers {
154	        out.push_str(&format!("{}: {}\r\n", k, v));
155	    }
156	    out.push_str(&format!(
157	        "Content-Length: {}\r\nConnection: close\r\n\r\n",
158	        response.body.len()
159	    ));
160	
161	    if (&stream).write_all(out.as_bytes()).is_err() {
162	        return;
163	    }
164	    if response.body.is_empty() {
165	        return;
166	    }
167	    let _ = (&stream).write_all(&response.body);
168	}
169	
170	fn read_head(reader: &mut BufReader<&TcpStream>) -> std::io::Result<Recorded> {
171	    let mut line = String::new();
172	    reader.read_line(&mut line)?;
173	    let mut parts = line.trim().split(' ');
174	    let method = parts.next().unwrap_or("").to_string();
175	    let target = parts.next().unwrap_or("").to_string();
176	
177	    let mut headers = vec![];
178	    loop {
179	        let mut l = String::new();
180	        reader.read_line(&mut l)?;
181	        let t = l.trim();
182	        if t.is_empty() {
183	            break;
184	        }
185	        if let Some((k, v)) = t.split_once(':') {
186	            headers.push((k.trim().to_string(), v.trim().to_string()));
187	        }
188	    }
189	
190	    Ok(Recorded {
191	        method,
192	        target,
193	        headers,
194	        body: vec![],
195	    })
196	}
197	
198	fn read_body(reader: &mut BufReader<&TcpStream>, req: &Recorded) -> std::io::Result<Vec<u8>> {
199	    if let Some(te) = req.header("transfer-encoding") {
200	        if te.to_ascii_lowercase().contains("chunked") {
201	            let mut body = vec![];
202	            loop {
203	                let mut size_line = String::new();
204	                reader.read_line(&mut size_line)?;
205	                let size_str = size_line.trim().split(';').next().unwrap();
206	                let size = usize::from_str_radix(size_str, 16)
207	                    .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
208	                if size == 0 {
209	                    // Trailers (if any) up to the empty line.
210	                    loop {
211	                        let mut l = String::new();
212	                        reader.read_line(&mut l)?;
213	                        if l.trim().is_empty() {
214	                            break;
215	                        }
216	                    }
217	                    break;
218	                }
219	                let mut chunk = vec![0u8; size];
220	                reader.read_exact(&mut chunk)?;
221	                body.extend_from_slice(&chunk);
222	                let mut crlf = [0u8; 2];
223	                reader.read_exact(&mut crlf)?;
224	            }
225	            return Ok(body);
226	        }
227	    }
228	
229	    if let Some(cl) = req.header("content-length") {
230	        let n: usize = cl.parse().unwrap();
231	        let mut body = vec![0u8; n];
232	        reader.read_exact(&mut body)?;
233	        return Ok(body);
234	    }
235	
236	    Ok(vec![])
237	}
