247	/// Server answering 307 for /a and 200 for /b.
248	fn redirect_307_server() -> Server {
249	    serve(|addr, req| {
250	        if req.target == "/a" {
251	            Reply::WithBody(Response::new(307).header("Location", &format!("http://{}/b", addr)))
252	        } else {
253	            Reply::WithBody(Response::new(200).body(b"made it"))
254	        }
255	    })
256	}
